(function(){'use strict';const KEY='buchee_dark_20261102';function apply(){let enabled=false;try{enabled=localStorage.getItem(KEY)==='1'}catch(e){}document.documentElement.classList.toggle('buchee-dark',enabled);document.documentElement.dataset.patiTheme=enabled?'dark':'light';const b=document.getElementById('buchee-theme-toggle');if(b){b.textContent=enabled?'☀':'☾';b.setAttribute('aria-label',enabled?'Açık temaya geç':'Koyu temaya geç');b.title=enabled?'Açık tema':'Koyu tema'}}function setup(){if(document.getElementById('buchee-theme-toggle'))return;const b=document.createElement('button');b.id='buchee-theme-toggle';b.type='button';b.setAttribute('aria-label','Koyu temaya geç');b.addEventListener('click',()=>{const now=!document.documentElement.classList.contains('buchee-dark');try{localStorage.setItem(KEY,now?'1':'0')}catch(e){}apply()});document.body.appendChild(b);apply()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',setup);else setup();apply()})();